    : JSON.stringify(["control", node.role, node.name]);
}

function placementOf(node: StructureNode, styles: readonly StructureStyle[]): string {
  return JSON.stringify([
    node.rect.x,
    node.rect.y,
    node.rect.width,
    node.rect.height,
    styles.map((style) => [style.property, style.value]),
  ]);
}

function prepare(nodes: readonly StructureNode[]): {
  readonly nodes: readonly PreparedNode[];
  readonly invalid: readonly number[];
} {
  const invalid: number[] = [];
  const prepared = nodes.map((node, index) => {
    const styles = [...node.styles].sort((left, right) =>
      compareText(left.property, right.property),
    );
    if (styles.some((style, position) => position > 0 && styles[position - 1].property === style.property)) {
      invalid.push(index);
    }
    return { node, styles };
  });
  return { nodes: prepared, invalid };
