  return indexes
    .filter((index) => !used.has(index))
    .sort((left, right) =>
      compareText(
        placementOf(nodes[left].node, nodes[left].styles),
        placementOf(nodes[right].node, nodes[right].styles),
      ) || left - right,
    );
}

