  const expectedStyles = new Map(expected.styles.map((style) => [style.property, style.value]));
  const actualStyles = new Map(actual.styles.map((style) => [style.property, style.value]));
  const properties = Array.from(new Set([...expectedStyles.keys(), ...actualStyles.keys()])).sort(compareText);
  for (const property of properties) {
    if (expectedStyles.get(property) !== actualStyles.get(property)) {
      drafts.push({ code: "style_changed", detail: property, expectedIndex, actualIndex });
